     1	package pousada.web;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import io.javalin.Javalin;
     6	import io.javalin.http.Context;
     7	import org.slf4j.Logger;
     8	import org.slf4j.LoggerFactory;
     9	import pousada.domain.ErrorCode;
    10	import pousada.domain.PousadaException;
    11	import pousada.domain.Reservation;
    12	import pousada.domain.RoomCatalog;
    13	import pousada.service.ReportService;
    14	import pousada.service.ReservationService;
    15	
    16	import java.util.LinkedHashMap;
    17	import java.util.Map;
    18	
    19	public final class Api {
    20	    private static final Logger LOG = LoggerFactory.getLogger(Api.class);
    21	
    22	    private final ObjectMapper mapper = new ObjectMapper().enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    23	    private final RequestParser parser = new RequestParser(mapper);
    24	    private final ReservationService reservations;
    25	    private final ReportService reports;
    26	
    27	    public Api(ReservationService reservations, ReportService reports) {
    28	        this.reservations = reservations;
    29	        this.reports = reports;
    30	    }
    31	
    32	    public Javalin create() {
    33	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    34	
    35	        app.get("/rooms", ctx -> json(ctx, 200, RoomCatalog.all().stream().map(Views::room).toList()));
    36	
    37	        app.post("/reservations", ctx ->
    38	                json(ctx, 201, Views.reservation(reservations.create(parser.newReservation(ctx.body())))));
    39	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(reservations.get(id(ctx)))));
    40	        app.post("/reservations/{id}/confirmation", ctx ->
    41	                json(ctx, 200, Views.reservation(reservations.confirm(id(ctx)))));
    42	        app.post("/reservations/{id}/cancellation", ctx ->
    43	                json(ctx, 200, Views.reservation(reservations.cancel(id(ctx)))));
    44	        app.post("/reservations/{id}/check-in", ctx ->
    45	                json(ctx, 200, Views.reservation(reservations.checkIn(id(ctx)))));
    46	        app.post("/reservations/{id}/check-out", ctx ->
    47	                json(ctx, 200, document(reservations.checkOut(id(ctx)))));
    48	        app.get("/reservations/{id}/document", ctx ->
    49	                json(ctx, 200, document(reservations.requirePaid(id(ctx)))));
    50	
    51	        app.get("/messages", ctx -> json(ctx, 200, reservations.messages().stream().map(Views::message).toList()));
    52	
    53	        app.get("/reports/occupancy", ctx -> csv(ctx,
    54	                reports.occupancy(RequestParser.date(ctx.queryParam("date"), "date"))));
    55	        app.get("/reports/revenue", ctx -> csv(ctx,
    56	                reports.revenue(RequestParser.month(ctx.queryParam("month")))));
    57	
    58	        app.exception(PousadaException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    59	        app.exception(Exception.class, (e, ctx) -> {
    60	            LOG.error("Erro inesperado", e);
    61	            json(ctx, 500, Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    62	        });
    63	        return app;
    64	    }
    65	
    66	    private Map<String, Object> document(Reservation reservation) {
    67	        return Views.document(reservation, reservations.document(reservation));
    68	    }
    69	
    70	    private void error(Context ctx, ErrorCode code, String message) {
    71	        Map<String, Object> body = new LinkedHashMap<>();
    72	        body.put("error", code.name());
    73	        body.put("message", message);
    74	        json(ctx, code.httpStatus(), body);
    75	    }
    76	
    77	    private void json(Context ctx, int status, Object body) {
    78	        try {
    79	            ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    80	        } catch (Exception e) {
    81	            throw new IllegalStateException(e);
    82	        }
    83	    }
    84	
    85	    private static void csv(Context ctx, String content) {
    86	        ctx.status(200).contentType("text/csv; charset=utf-8").result(content);
    87	    }
    88	
    89	    private static long id(Context ctx) {
    90	        try {
    91	            return Long.parseLong(ctx.pathParam("id"));
    92	        } catch (NumberFormatException e) {
    93	            throw new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe");
    94	        }
    95	    }
    96	}
