     1	package pousada.web;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	import pousada.domain.PousadaException;
     7	import pousada.domain.RatePlan;
     8	import pousada.identity.IdentityKinds;
     9	import pousada.service.NewReservation;
    10	
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeParseException;
    14	import java.util.HashMap;
    15	import java.util.Map;
    16	import java.util.regex.Pattern;
    17	
    18	final class RequestParser {
    19	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    20	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    21	
    22	    private final ObjectMapper mapper;
    23	
    24	    RequestParser(ObjectMapper mapper) {
    25	        this.mapper = mapper;
    26	    }
    27	
    28	    NewReservation newReservation(String body) {
    29	        JsonNode json = parseObject(body);
    30	        LocalDate checkIn = date(text(json, "checkIn"), "checkIn");
    31	        LocalDate checkOut = date(text(json, "checkOut"), "checkOut");
    32	        if (!checkOut.isAfter(checkIn)) {
    33	            throw PousadaException.invalid("A saída deve ser depois da entrada");
    34	        }
    35	        int guests = integer(json, "guests");
    36	        if (guests < 1) {
    37	            throw PousadaException.invalid("É preciso pelo menos um hóspede");
    38	        }
    39	        return new NewReservation(
    40	                integer(json, "roomNumber"),
    41	                text(json, "guestName"),
    42	                text(json, "guestEmail"),
    43	                IdentityKinds.fromRequest(identityFields(json)),
    44	                checkIn,
    45	                checkOut,
    46	                guests,
    47	                ratePlan(text(json, "ratePlan")));
    48	    }
    49	
    50	    static LocalDate date(String value, String name) {
    51	        if (value == null || !DATE.matcher(value).matches()) {
    52	            throw PousadaException.invalid("Data inválida em " + name + " (use AAAA-MM-DD)");
    53	        }
    54	        try {
    55	            return LocalDate.parse(value);
    56	        } catch (DateTimeParseException e) {
    57	            throw PousadaException.invalid("Data inválida em " + name + " (use AAAA-MM-DD)");
    58	        }
    59	    }
    60	
    61	    static YearMonth month(String value) {
    62	        if (value == null || !MONTH.matcher(value).matches()) {
    63	            throw PousadaException.invalid("Mês inválido (use AAAA-MM)");
    64	        }
    65	        try {
    66	            return YearMonth.parse(value);
    67	        } catch (DateTimeParseException e) {
    68	            throw PousadaException.invalid("Mês inválido (use AAAA-MM)");
    69	        }
    70	    }
    71	
    72	    private JsonNode parseObject(String body) {
    73	        try {
    74	            JsonNode json = mapper.readTree(body);
    75	            if (json == null || !json.isObject()) {
    76	                throw PousadaException.invalid("O corpo deve ser um objeto JSON");
    77	            }
    78	            return json;
    79	        } catch (JsonProcessingException e) {
    80	            throw PousadaException.invalid("O corpo não é um JSON válido");
    81	        }
    82	    }
    83	
    84	    private static Map<String, String> identityFields(JsonNode json) {
    85	        Map<String, String> given = new HashMap<>();
    86	        for (String name : IdentityKinds.allFieldNames()) {
    87	            if (json.hasNonNull(name)) {
    88	                given.put(name, text(json, name));
    89	            }
    90	        }
    91	        return given;
    92	    }
    93	
    94	    private static String text(JsonNode json, String name) {
    95	        JsonNode node = json.get(name);
    96	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    97	            throw PousadaException.invalid("Campo obrigatório: " + name);
    98	        }
    99	        return node.asText();
   100	    }
   101	
   102	    private static int integer(JsonNode json, String name) {
   103	        JsonNode node = json.get(name);
   104	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
   105	            throw PousadaException.invalid("Campo obrigatório (número inteiro): " + name);
   106	        }
   107	        return node.asInt();
   108	    }
   109	
   110	    private static RatePlan ratePlan(String value) {
   111	        try {
   112	            return RatePlan.valueOf(value);
   113	        } catch (IllegalArgumentException e) {
   114	            throw PousadaException.invalid("Plano de tarifa inválido: " + value);
   115	        }
   116	    }
   117	}
