     1	package pousada.service;
     2	
     3	import pousada.document.IssuedDocument;
     4	import pousada.domain.Channel;
     5	import pousada.domain.ErrorCode;
     6	import pousada.domain.Message;
     7	import pousada.domain.PousadaException;
     8	import pousada.domain.Quote;
     9	import pousada.domain.Reservation;
    10	import pousada.domain.Room;
    11	import pousada.domain.RoomCatalog;
    12	import pousada.persistence.Database;
    13	import pousada.persistence.MessageRepository;
    14	import pousada.persistence.ReservationRepository;
    15	
    16	import java.util.List;
    17	import java.util.function.UnaryOperator;
    18	
    19	public final class ReservationService {
    20	    private final Database db;
    21	    private final ReservationRepository reservations = new ReservationRepository();
    22	    private final MessageRepository messages = new MessageRepository();
    23	
    24	    public ReservationService(Database db) {
    25	        this.db = db;
    26	    }
    27	
    28	    public Reservation create(NewReservation request) {
    29	        Room room = RoomCatalog.require(request.roomNumber());
    30	        if (request.guests() > room.capacity()) {
    31	            throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    32	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    33	        }
    34	        Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    35	        Reservation pending = Reservation.pending(room.number(), request.guestName(), request.guestEmail(),
    36	                request.identity(), request.checkIn(), request.checkOut(), request.guests(),
    37	                request.ratePlan(), quote);
    38	        return db.tx(c -> {
    39	            reservations.lockRoom(c, room.number());
    40	            if (reservations.hasActiveOverlap(c, room.number(), request.checkIn(), request.checkOut())) {
    41	                throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE,
    42	                        "O quarto " + room.number() + " já está reservado em alguma das noites");
    43	            }
    44	            return reservations.insert(c, pending);
    45	        });
    46	    }
    47	
    48	    public Reservation get(long id) {
    49	        return db.tx(c -> reservations.find(c, id).orElseThrow(() -> notFound(id)));
    50	    }
    51	
    52	    public Reservation confirm(long id) {
    53	        return db.tx(c -> {
    54	            Reservation confirmed = reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id)).confirm();
    55	            reservations.updateState(c, confirmed);
    56	            messages.add(c, Channel.EMAIL, confirmed.guestEmail(), ConfirmationEmail.SUBJECT,
    57	                    ConfirmationEmail.body(confirmed.guestName(), document(confirmed).text()));
    58	            return confirmed;
    59	        });
    60	    }
    61	
    62	    public Reservation cancel(long id) {
    63	        return transition(id, Reservation::cancel);
    64	    }
    65	
    66	    public Reservation checkIn(long id) {
    67	        return transition(id, Reservation::registerCheckIn);
    68	    }
    69	
    70	    public Reservation checkOut(long id) {
    71	        return transition(id, Reservation::registerCheckOut);
    72	    }
    73	
    74	    /** Segunda via: só existe para reserva paga. */
    75	    public Reservation requirePaid(long id) {
    76	        Reservation reservation = get(id);
    77	        if (!reservation.status().isPaid()) {
    78	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    79	                    "Reserva " + reservation.status() + " não tem comprovante");
    80	        }
    81	        return reservation;
    82	    }
    83	
    84	    public IssuedDocument document(Reservation reservation) {
    85	        Room room = RoomCatalog.require(reservation.roomNumber());
    86	        return reservation.identity().issue(reservation.stay(room));
    87	    }
    88	
    89	    public List<Message> messages() {
    90	        return db.tx(messages::all);
    91	    }
    92	
    93	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    94	        return db.tx(c -> {
    95	            Reservation changed = change.apply(reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id)));
    96	            reservations.updateState(c, changed);
    97	            return changed;
    98	        });
    99	    }
   100	
   101	    private static PousadaException notFound(long id) {
   102	        return new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
   103	    }
   104	}

