     1	package pousada.document;
     2	
     3	import java.math.BigDecimal;
     4	import java.text.DecimalFormat;
     5	import java.text.DecimalFormatSymbols;
     6	import java.time.LocalDate;
     7	import java.time.format.DateTimeFormatter;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	
    11	/**
    12	 * Idioma e formatos de um documento, e a sequência de linhas que todos eles seguem.
    13	 * Cada tipo de documento só informa o título, as linhas de identificação e o rodapé.
    14	 */
    15	public record Wording(
    16	        String numberSign,
    17	        String roomLabel,
    18	        String checkInLabel,
    19	        String checkOutLabel,
    20	        String oneNight,
    21	        String manyNights,
    22	        String subtotalLabel,
    23	        String discountLabel,
    24	        String totalLabel,
    25	        String moneyPrefix,
    26	        char groupingSeparator,
    27	        char decimalSeparator,
    28	        DateTimeFormatter dateFormat) {
    29	
    30	    public static final Wording PORTUGUESE = new Wording("nº", "Quarto", "Entrada", "Saída",
    31	            "diária", "diárias", "Diárias", "Desconto", "Total",
    32	            "R$ ", '.', ',', DateTimeFormatter.ofPattern("dd/MM/yyyy"));
    33	
    34	    public static final Wording ENGLISH = new Wording("no.", "Room", "Check-in", "Check-out",
    35	            "night", "nights", "Nights", "Discount", "Total",
    36	            "BRL ", ',', '.', DateTimeFormatter.ISO_LOCAL_DATE);
    37	
    38	    public String money(BigDecimal value) {
    39	        DecimalFormatSymbols symbols = new DecimalFormatSymbols();
    40	        symbols.setGroupingSeparator(groupingSeparator);
    41	        symbols.setDecimalSeparator(decimalSeparator);
    42	        return moneyPrefix + new DecimalFormat("#,##0.00", symbols).format(value);
    43	    }
    44	
    45	    public String date(LocalDate date) {
    46	        return dateFormat.format(date);
    47	    }
    48	
    49	    public String render(String title, Stay stay, List<String> identityLines, List<String> footerLines) {
    50	        List<String> lines = new ArrayList<>();
    51	        lines.add(title + " " + numberSign + " " + stay.reservationId());
    52	        lines.addAll(identityLines);
    53	        lines.add(roomLabel + ": " + stay.roomNumber() + " (" + stay.roomType() + ")");
    54	        lines.add(checkInLabel + ": " + date(stay.checkIn()) + " | " + checkOutLabel + ": " + date(stay.checkOut())
    55	                + " | " + stay.nights() + " " + (stay.nights() == 1 ? oneNight : manyNights));
    56	        lines.add(subtotalLabel + ": " + money(stay.subtotal()));
    57	        if (stay.discount().signum() > 0) {
    58	            lines.add(discountLabel + ": " + money(stay.discount()));
    59	        }
    60	        lines.add(totalLabel + ": " + money(stay.total()));
    61	        lines.addAll(footerLines);
    62	        return String.join("\n", lines);
    63	    }
    64	}
