     7	
     8	/** Lista das formas de identificação aceitas. Uma nova forma entra aqui, e só aqui. */
     9	public final class IdentityKinds {
    10	    private static final List<IdentityKind> ALL = List.of(
    11	            CpfIdentity.KIND,
    12	            CnpjIdentity.KIND,
    13	            PassportIdentity.KIND);
    14	
    15	    private IdentityKinds() {
    16	    }
    17	
    18	    /** Todos os campos de identificação que a reserva expõe, na ordem de declaração. */
    19	    public static List<String> allFieldNames() {
    20	        return ALL.stream().flatMap(k -> k.fieldNames().stream()).toList();
    21	    }
    22	
    23	    /** Escolhe a única forma de identificação cujos campos vieram; qualquer outra combinação é inválida. */
    24	    public static Identity fromRequest(Map<String, String> given) {
    25	        List<IdentityKind> used = ALL.stream()
    26	                .filter(k -> k.fieldNames().stream().anyMatch(given::containsKey))
    27	                .toList();
    28	        if (used.size() != 1) {
    29	            throw PousadaException.invalid("Informe a identificação de um só jeito: "
    30	                    + String.join(" ou ", ALL.stream().map(k -> String.join("+", k.fieldNames())).toList()));
    31	        }
    32	        return used.get(0).create(given);
    33	    }
    34	
    35	    public static Identity restore(String kindName, Map<String, String> fields) {
    36	        return ALL.stream().filter(k -> k.name().equals(kindName)).findFirst()
    37	                .orElseThrow(() -> new IllegalStateException("Identificação desconhecida: " + kindName))
    38	                .create(fields);
    39	    }
    40	}
