     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	
    10	public final class Database implements AutoCloseable {
    11	    private static final String[] SCHEMA = {
    12	            """
    13	            CREATE TABLE IF NOT EXISTS reservations (
    14	                id BIGSERIAL PRIMARY KEY,
    15	                room_number INT NOT NULL,
    16	                guest_name TEXT NOT NULL,
    17	                guest_email TEXT NOT NULL,
    18	                identity_kind TEXT NOT NULL,
    19	                identity_data TEXT NOT NULL,
    20	                check_in DATE NOT NULL,
    21	                check_out DATE NOT NULL,
    22	                guests INT NOT NULL,
    23	                rate_plan TEXT NOT NULL,
    24	                nights INT NOT NULL,
    25	                subtotal NUMERIC(14,2) NOT NULL,
    26	                discount NUMERIC(14,2) NOT NULL,
    27	                total NUMERIC(14,2) NOT NULL,
    28	                status TEXT NOT NULL,
    29	                amount_paid NUMERIC(14,2) NOT NULL,
    30	                refund NUMERIC(14,2)
    31	            )""",
    32	            "CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out)",
    33	            "CREATE INDEX IF NOT EXISTS reservations_check_in ON reservations (check_in)",
    34	            """
    35	            CREATE TABLE IF NOT EXISTS messages (
    36	                id BIGSERIAL PRIMARY KEY,
    37	                channel TEXT NOT NULL,
    38	                recipient TEXT NOT NULL,
    39	                subject TEXT NOT NULL,
    40	                body TEXT NOT NULL
    41	            )"""
    42	    };
    43	
    44	    @FunctionalInterface
    45	    public interface Work<T> {
    46	        T run(Connection connection) throws SQLException;
    47	    }
    48	
    49	    private final HikariDataSource dataSource;
    50	
    51	    private Database(HikariDataSource dataSource) {
    52	        this.dataSource = dataSource;
    53	    }
    54	
    55	    /** Conecta (esperando o banco subir, se preciso) e cria o que faltar. */
    56	    public static Database connect(String url, String user, String password) {
    57	        HikariConfig config = new HikariConfig();
    58	        config.setJdbcUrl(url);
    59	        config.setUsername(user);
    60	        config.setPassword(password);
    61	        config.setMaximumPoolSize(10);
    62	        config.setInitializationFailTimeout(60_000);
    63	        Database database = new Database(new HikariDataSource(config));
    64	        database.migrate();
    65	        return database;
    66	    }
    67	
    68	    private void migrate() {
    69	        tx(connection -> {
    70	            try (Statement statement = connection.createStatement()) {
    71	                // Serializa a criação do schema caso duas instâncias subam juntas.
    72	                statement.execute("SELECT pg_advisory_xact_lock(7070)");
    73	                for (String ddl : SCHEMA) {
    74	                    statement.execute(ddl);
    75	                }
    76	            }
    77	            return null;
    78	        });
    79	    }
    80	
    81	    public <T> T tx(Work<T> work) {
    82	        try (Connection connection = dataSource.getConnection()) {
    83	            connection.setAutoCommit(false);
    84	            try {
    85	                T result = work.run(connection);
    86	                connection.commit();
    87	                return result;
    88	            } catch (Throwable e) {
    89	                connection.rollback();
    90	                throw e;
    91	            }
    92	        } catch (SQLException e) {
    93	            throw new IllegalStateException("Erro de banco de dados", e);
    94	        }
    95	    }
    96	
    97	    @Override
    98	    public void close() {
    99	        dataSource.close();
   100	    }
   101	}
