    31	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    32	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, identity_kind, identity_data, "
    33	                + "check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    34	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    35	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    36	            ps.setInt(1, r.roomNumber());
    37	            ps.setString(2, r.guestName());
    38	            ps.setString(3, r.guestEmail());
    39	            ps.setString(4, r.identity().kind().name());
    40	            ps.setString(5, write(r.identity().fields()));
    41	            ps.setObject(6, r.checkIn());
    42	            ps.setObject(7, r.checkOut());
    43	            ps.setInt(8, r.guests());
    44	            ps.setString(9, r.ratePlan().name());
    45	            ps.setInt(10, r.quote().nights());
    46	            ps.setBigDecimal(11, r.quote().subtotal());
    47	            ps.setBigDecimal(12, r.quote().discount());
    48	            ps.setBigDecimal(13, r.quote().total());
    49	            ps.setString(14, r.status().name());
    50	            ps.setBigDecimal(15, r.amountPaid());
    51	            ps.setBigDecimal(16, r.refund());
    52	            ps.executeUpdate();
    53	            try (ResultSet keys = ps.getGeneratedKeys()) {
    54	                keys.next();
    55	                return r.withId(keys.getLong("id"));
    56	            }
    57	        }
    58	    }
    59	
    60	    public void updateState(Connection c, Reservation r) throws SQLException {
    61	        try (PreparedStatement ps = c.prepareStatement(
    62	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    63	            ps.setString(1, r.status().name());
    64	            ps.setBigDecimal(2, r.amountPaid());
    65	            ps.setBigDecimal(3, r.refund());
    66	            ps.setLong(4, r.id());
    67	            ps.executeUpdate();
    68	        }
    69	    }
