    80	    /** Serializa as reservas concorrentes do mesmo quarto até o fim da transação. */
    81	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    82	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    83	            ps.setLong(1, roomNumber);
    84	            ps.execute();
    85	        }
    86	    }
    87	
    88	    public boolean hasActiveOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    89	            throws SQLException {
    90	        try (PreparedStatement ps = c.prepareStatement(
    91	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    92	                        + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    93	            ps.setInt(1, roomNumber);
    94	            ps.setObject(2, checkOut);
    95	            ps.setObject(3, checkIn);
    96	            try (ResultSet rs = ps.executeQuery()) {
    97	                return rs.next();
    98	            }
    99	        }
   100	    }
   101	
   102	    /** Reservas pagas que ocupam o quarto na noite, por número do quarto. */
   103	    public List<Reservation> paidOccupying(Connection c, LocalDate night) throws SQLException {
   104	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE status IN " + PAID
   105	                + " AND check_in <= ? AND check_out > ? ORDER BY room_number, id", night, night);
   106	    }
   107	
   108	    /** Reservas que começam no período e deixaram dinheiro com a pousada, por entrada e número. */
   109	    public List<Reservation> keptMoneyStartingBetween(Connection c, LocalDate from, LocalDate toExclusive)
   110	            throws SQLException {
   111	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   112	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id", from, toExclusive);
   113	    }
   114	
   115	    private Optional<Reservation> findOne(Connection c, String sql, long id) throws SQLException {
   116	        try (PreparedStatement ps = c.prepareStatement(sql)) {
   117	            ps.setLong(1, id);
   118	            try (ResultSet rs = ps.executeQuery()) {
   119	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
   120	            }
   121	        }
   122	    }
   123	
   124	    private List<Reservation> query(Connection c, String sql, Object... params) throws SQLException {
   125	        try (PreparedStatement ps = c.prepareStatement(sql)) {
   126	            for (int i = 0; i < params.length; i++) {
   127	                ps.setObject(i + 1, params[i]);
   128	            }
   129	            try (ResultSet rs = ps.executeQuery()) {
   130	                List<Reservation> result = new ArrayList<>();
   131	                while (rs.next()) {
   132	                    result.add(read(rs));
   133	                }
   134	                return result;
   135	            }
   136	        }
   137	    }
   138	
   139	    private Reservation read(ResultSet rs) throws SQLException {
   140	        Identity identity = IdentityKinds.restore(rs.getString("identity_kind"), readFields(rs.getString("identity_data")));
   141	        Quote quote = new Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   142	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   143	        return new Reservation(
   144	                rs.getLong("id"),
   145	                rs.getInt("room_number"),
   146	                rs.getString("guest_name"),
   147	                rs.getString("guest_email"),
   148	                identity,
   149	                rs.getObject("check_in", LocalDate.class),
   150	                rs.getObject("check_out", LocalDate.class),
   151	                rs.getInt("guests"),
   152	                RatePlan.valueOf(rs.getString("rate_plan")),
   153	                quote,
   154	                ReservationStatus.valueOf(rs.getString("status")),
   155	                rs.getBigDecimal("amount_paid"),
   156	                rs.getBigDecimal("refund"));
   157	    }
   158	
   159	    private String write(Map<String, String> fields) {
   160	        try {
   161	            return mapper.writeValueAsString(fields);
   162	        } catch (JsonProcessingException e) {
   163	            throw new IllegalStateException(e);
   164	        }
   165	    }
   166	
   167	    private Map<String, String> readFields(String json) {
   168	        try {
   169	            return mapper.readValue(json, new TypeReference<>() {
   170	            });
   171	        } catch (JsonProcessingException e) {
   172	            throw new IllegalStateException(e);
   173	        }
   174	    }
   175	}
