 48	            s.execute("CREATE SCHEMA " + schema);
 49	        } catch (Exception e) {
 50	            Assumptions.abort("banco indisponível: " + e.getMessage());
 51	        }
 52	        db = Database.connect(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
