 74	    private static Resp call(String method, String path, String body) throws Exception {
 75	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 76	        if (body == null) {
 77	            b.method(method, HttpRequest.BodyPublishers.noBody());
 78	        } else {
 79	            b.method(method, HttpRequest.BodyPublishers.ofString(body)).header("Content-Type", "application/json");
 80	        }
 81	        HttpResponse<String> r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 82	        return new Resp(r.statusCode(), r.body(), r.headers().firstValue("Content-Type").orElse(""));
 83	    }
