104	
105	        assertEquals(404, call("GET", "/reservations/999999", null).status());
106	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).status());
107	        assertEquals(409, call("POST", "/reservations/" + id + "/check-in", null).status());
108	
109	        Resp conflict = call("POST", "/reservations", reservation(201, "2031-03-11", "2031-03-13", 1, "STANDARD", CPF));
110	        assertEquals(409, conflict.status());
