 40	    @BeforeAll
 41	    static void start() throws Exception {
 42	        url = System.getenv("DB_URL");
 43	        user = System.getenv("DB_USER");
 44	        password = System.getenv("DB_PASSWORD");
 45	        Assumptions.assumeTrue(url != null, "DB_URL ausente");
 46	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 47	        try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
 48	            s.execute("CREATE SCHEMA " + schema);
 49	        } catch (Exception e) {
 50	            Assumptions.abort("banco indisponível: " + e.getMessage());
 51	        }
 52	        db = Database.connect(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
 53	        app = new Api(new ReservationService(db), new ReportService(db)).create().start(0);
 54	        base = "http://localhost:" + app.port();
 55	    }
 56	
 57	    @AfterAll
 58	    static void stop() throws Exception {
 59	        if (app != null) app.stop();
 60	        if (db != null) db.close();
 61	        if (schema != null) {
 62	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
 63	                s.execute("DROP SCHEMA " + schema + " CASCADE");
 64	            }
 65	        }
 66	    }
